import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const DIST = process.argv[2];
const PORT = Number(process.argv[3] || 8731);

export const posts = [];

const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".json": "application/json",
  ".woff2": "font/woff2",
};

const ME = {
  id: "u1",
  email: "admin@example.com",
  display_name: "관리자",
  department: "기술",
  organization_name: "Momento",
  role: "owner",
};
const SITE = {
  id: "s1",
  site_id: "site-one",
  name: "사이트 하나",
  service_name: "svc",
  allowed_domains: ["example.com"],
  session_timeout_minutes: 30,
  timezone: "Asia/Seoul",
  engagement_threshold_seconds: 10,
  active: true,
  tracking_key_prefix: "pk_",
  server_api_key_prefix: "sk_",
  workspace: "w",
  organization: "o",
  created_at: "2026-01-01T00:00:00Z",
};

function json(res, status, body) {
  const text = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(text),
  });
  res.end(text);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  const p = url.pathname;

  if (p.startsWith("/api/")) {
    if (req.method === "POST" && p === "/api/v1/event-definitions") {
      let body = "";
      req.on("data", (c) => (body += c));
      req.on("end", () => {
        posts.push(body);
        json(res, 200, { ok: true });
      });
      return;
    }
    if (p === "/api/v1/me") return json(res, 200, ME);
    if (p === "/api/v1/sites") return json(res, 200, [SITE]);
    if (p.endsWith("/environments"))
      return json(res, 200, [
        {
          name: "prd",
          label: "운영",
          contract_mode: "warn",
          cardinality_limit: 100,
          active: true,
        },
      ]);
    if (p === "/api/v1/event-definitions") return json(res, 200, []);
    return json(res, 200, []);
  }

  let file = path.join(DIST, p === "/" ? "index.html" : p);
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory())
    file = path.join(DIST, "index.html");
  const type = TYPES[path.extname(file)] || "application/octet-stream";
  res.writeHead(200, { "content-type": type });
  fs.createReadStream(file).pipe(res);
});

server.listen(PORT, () => console.log(`READY ${PORT}`));

process.on("message", (m) => {
  if (m === "posts") process.send({ posts });
});
export { server };
import puppeteer from "puppeteer-core";
import { posts } from "./server.mjs";

const PORT = Number(process.argv[3] || 8731);
const BASE = `http://127.0.0.1:${PORT}`;

const RULE =
  "「JSON Schema」 칸의 내용이 올바른 JSON 이 아닙니다. 중괄호·대괄호의 짝과 쉼표 위치를 확인하고, 키와 문자열 값은 겹따옴표로 감싸세요. 규격을 비워 둘 때는 {} 로 적습니다.";
const HELP = "속성 규격을 JSON 으로 적습니다. 비워 둘 때는 {} 로 적으세요.";
const ENGINE = [
  "Unexpected token",
  "is not valid JSON",
  "position",
  "JSON.parse",
  "Unexpected end of",
];

const fails = [];
const ok = (cond, label, extra = "") => {
  if (cond) console.log(`PASS ${label}`);
  else {
    console.log(`FAIL ${label}${extra ? " — " + extra : ""}`);
    fails.push(label);
  }
};

const browser = await puppeteer.launch({
  executablePath: "/usr/bin/google-chrome",
  headless: true,
  args: ["--no-sandbox", "--disable-dev-shm-usage"],
});

// useUnsavedWarning 이 폼을 채운 탭의 재이동을 beforeunload 로 막으므로
// (components/useUnsavedWarning.ts) 사례마다 새 탭을 쓴다.
async function openForm(schemaText, { name = "signup" } = {}) {
  const page = await browser.newPage();
  page.on("dialog", (d) => d.accept());
  await page.goto(`${BASE}/admin?section=schemas`, {
    waitUntil: "networkidle2",
  });
  await page.waitForFunction(
    () =>
      [...document.querySelectorAll("label")].some(
        (l) => l.textContent.trim() === "JSON Schema",
      ),
    { timeout: 20000 },
  );
  const fill = async (labelText, value) => {
    const handle = await page.evaluateHandle((t) => {
      const label = [...document.querySelectorAll("label")].find(
        (l) => l.textContent.trim() === t,
      );
      return document.getElementById(label.getAttribute("for"));
    }, labelText);
    await handle.click({ clickCount: 3 });
    await page.keyboard.down("Control");
    await page.keyboard.press("KeyA");
    await page.keyboard.up("Control");
    await page.keyboard.press("Backspace");
    if (value) await handle.type(value);
  };
  await fill("Event name", name);
  await fill("JSON Schema", schemaText);
  return page;
}

async function read(page) {
  return page.evaluate(() => {
    const label = [...document.querySelectorAll("label")].find(
      (l) => l.textContent.trim() === "JSON Schema",
    );
    const root = label.closest(".MuiFormControl-root");
    const helper = root.querySelector(".MuiFormHelperText-root");
    const save = [...document.querySelectorAll("button")].find(
      (b) => b.textContent.trim() === "저장",
    );
    return {
      helper: helper ? helper.textContent.trim() : null,
      errored: !!root.querySelector(".Mui-error"),
      disabled: save ? save.disabled : null,
      value: root.querySelector("textarea").value,
    };
  });
}

// --- 1. 깨진 JSON: 누르기 전에 안내가 보이고 「저장」 이 닫힌다 -------------
{
  const page = await openForm('{"properties": }');
  const s = await read(page);
  ok(s.helper === RULE, "깨진 JSON: helperText 가 저장 실패 Alert 과 같은 문장", `helper=${JSON.stringify(s.helper)}`);
  ok(s.errored, "깨진 JSON: 칸이 오류 색으로 칠해진다");
  ok(s.disabled === true, "깨진 JSON: 「저장」 이 닫힌다", `disabled=${s.disabled}`);
  const leaked = ENGINE.filter((m) => (s.helper || "").includes(m));
  ok(leaked.length === 0, "깨진 JSON: helperText 에 V8 영문 표지가 0개", `샌 것: ${leaked}`);
  ok(posts.length === 0, "깨진 JSON: 서버에 POST 0건", `posts=${posts.length}`);
  await page.close();
}

// --- 2. 올바른 값 네 가지는 막지 않는다 ------------------------------------
for (const good of ["{}", '{"properties":{}}', "null", "[1,2]"]) {
  const page = await openForm(good);
  const s = await read(page);
  ok(s.value === good, `올바른 값 ${good}: 입력이 그대로 들어갔다`, `value=${s.value}`);
  ok(s.helper === HELP, `올바른 값 ${good}: 기본 설명이 선다`, `helper=${s.helper}`);
  ok(!s.errored, `올바른 값 ${good}: 오류 색이 아니다`);
  ok(s.disabled === false, `올바른 값 ${good}: 「저장」 이 열려 있다`, `disabled=${s.disabled}`);
  await page.close();
}

// --- 3. 빈 칸은 닫되 칠하지 않는다 -----------------------------------------

